<template>
  <div class="app" id="app">
    <div class="app__aside">
      <div class="app__menu">
        <div class="mode-select">
          <select @change="changeMode">
            <option v-for="mode in modes" :value="mode.id">{{ mode.title }} ({{ mode.questions.length }} вопросов)</option>
          </select>
        </div>
        <div class="menu">
          <!-- current = Math.min(index, current) -->
          <div v-for="question, index in questions" :key="question.title" @click="current = index" :class="{
            'menu__item': true,
            'menu__item_active': current === index,
            'menu__item_resolved': index in responses,
            'menu__item_passed': responses[index] === 0.5,
            'menu__item_confirmed': responses[index] === 1,
            'menu__item_rejected': responses[index] === 0,
          }">
            <div class="menu__id">{{ question.id }}</div>
            <div class="menu__title">{{ question.title }}</div>
          </div>
        </div>
      </div>
    </div>
    <div class="app__main">
      <div class="app__slide">
        <div v-if="current === -1">
          <h1 class="title">Добро пожаловать!</h1>
          <h2 class="subtitle">Вас приветствуют создатели программы установления факта письма непривычной пишущей рукой.</h2>
          <div class="buttons-row">
            <button class="button" @click="start">Начать</button>
          </div>
        </div>
        <div v-else-if="current === questions.length">
          <h1 class="title">Ваш результат</h1>
          <h2 class="subtitle">{{ result.sum }}</h2>
          <h2 class="subtitle">{{ result.title }}</h2>
          <div class="buttons-row">
            <button class="button button_blue" @click="copy">Скопировать таблицу</button>
            <button class="button" @click="reset">Сбросить и вернуться в начало</button>
          </div>
          <div class="app__copy-table">
            <table border="1" cellpadding="5">
              <thead>
                <tr>
                  <th>№</th>
                  <th>Наименование признака</th>
                  <th>log P(П)/P(H)</th>
                  <th>log(1 - P(П))/(1 - P(H))</th>
                  <th>Наличие (1) или отсутствие (0) признака в тексте</th>
                  <th>Вычисление обобщенного критерия</th>
                </tr>
              </thead>
              <tbody>
                <tr v-for="(response, index) in responses">
                  <td>
                    <nobr>{{ index + 1 }}</nobr>
                  </td>
                  <td>{{ questions[index].title }}</td>
                  <td>
                    <nobr>{{ questions[index].min }}</nobr>
                  </td>
                  <td>
                    <nobr>{{ questions[index].max }}</nobr>
                  </td>
                  <td>
                    <nobr>{{ response || '—' }}</nobr>
                  </td>
                  <td>
                    <nobr v-if="response">{{ ((questions[index].min * response) + (questions[index].max * (1 - response))).toFixed(2) }}</nobr>
                    <template v-else>—</template>
                  </td>
                </tr>
              </tbody>
              <tfoot>
                <tr>
                  <td></td>
                  <td colspan="5">Итого</td>
                </tr>
                <tr>
                  <td></td>
                  <td>Результат</td>
                  <td colspan="4">{{ result.title }}</td>
                </tr>
                <tr>
                  <td></td>
                  <td>Сумма значений критериев</td>
                  <td colspan="4">{{ result.sum }}</td>
                </tr>
                <tr>
                  <td></td>
                  <td>Доверительная точность</td>
                  <td colspan="4">{{ currentMode.accuracy * 100 }}%</td>
                </tr>
              </tfoot>
            </table>
          </div>
        </div>
        <div v-else>
          <h1 class="title">{{ questions[current].title }}</h1>
          <div class="description" v-html="questions[current].description"></div>
          <div class="photos-row" v-if="questions[current].photos.length">
            <img :src="photo" v-for="photo in questions[current].photos" />
          </div>
          <div class="buttons-row">
            <button class="button button_red" v-if="questions[current].allowed.includes(0)" @click="confirm(0)">Признак отсутствует</button>
            <button class="button button_green" v-if="questions[current].allowed.includes(1)" @click="confirm(1)">Признак присутствует</button>
            <button class="button" v-if="questions[current].allowed.includes(0.5)" @click="confirm(0.5)">Не учитывать признак</button>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import source from '@/assets/questionsSource.json';

export default {
  name: 'Quiz',
  data () {
    return {
      current: -1,
      responses: [],
      questionsSource: source.questions,
      modes: source.modes,
      currentModeId: source.modes[0].id,
    }
  },
  computed: {
    currentMode: function () {
      return this.modes.find((mode) => {
        return mode.id === this.currentModeId
      })
    },
    resultSum: function () {
      return this.responses.reduce((sum, item, index) => {
        return sum += (this.questions[index].min * item) + (this.questions[index].max * (1 - item))
      }, 0)
    },
    resultTitle: function () {
      return this.currentMode.results.find((variant) => {
        if (variant.to && variant.from) {
          return variant.from <= this.resultSum && this.resultSum <= variant.to
        } else if (variant.to && !variant.from) {
          return this.resultSum < variant.to
        } else if (!variant.to && variant.from) {
          return variant.from < this.resultSum
        } else {
          return false
        }
      }).title
    },
    result: function () {
      return {
        sum: this.resultSum.toFixed(3),
        title: this.resultTitle,
      }
    },
    questions: function () {
      return this.questionsSource.filter((question) => {
        return this.currentMode.questions.includes(question.id)
      })
    }
  },
  methods: {
    changeMode: function (event) {
      this.currentModeId = Number(event.target.value)
      this.responses.length = this.currentMode.questions.length

      if (this.current > this.currentMode.questions.length) {
        this.current = this.responses.length
      }
    },
    start: function () {
      this.current = 0
    },
    confirm: function (response) {
      this.responses[this.current] = response
      this.current++
    },
    reset: function () {
      this.current = -1
      this.responses.length = 0
    },
    copy: function () {
      const table = document.querySelector('.app__copy-table > table')
      const tableHTML = table.outerHTML
      const blobHTML = new Blob([tableHTML], {
        type: 'text/html'
      })

      const clipboardItem = new ClipboardItem({
        'text/html': blobHTML
      })

      navigator.clipboard.write([clipboardItem]).then(() => {
        alert('Таблица скопирована! Для того чтобы вставить, откройте документ и нажмите Ctrl+V')
      }, (err) => {
        alert('Простите, не удалось скопировать. Вы можете сделать скриншот таблицы и вставить её как картинку')
      });
    },
  }
}
</script>

